class Solution:
    def palindromeQueries(self, n: int, edges: List[List[int]], s: str, queries: List[str]) -> List[bool]:
        LOG = max(1, n.bit_length())
        adj = [[] for _ in range(n)]
        for u, v in edges:
            adj[u].append(v); adj[v].append(u)
        dep = [0]*n; tin = [0]*n; tout = [0]*n
        par = [[0]*n for _ in range(LOG)]
        timer = 0
        stk = [(0, -1, 0)]
        while stk:
            u, p, ph = stk.pop()
            if ph:
                tout[u] = timer; timer += 1; continue
            tin[u] = timer; timer += 1
            par[0][u] = p if p >= 0 else 0
            dep[u] = 0 if p < 0 else dep[p] + 1
            stk.append((u, p, 1))
            for w in adj[u]:
                if w != p: stk.append((w, u, 0))
        for k in range(1, LOG):
            up = par[k-1]
            par[k] = [up[up[u]] for u in range(n)]
        sz = 2*n + 2
        bit = [0]*sz
        def add(i, d):
            i += 1
            while i < sz:
                bit[i] ^= d; i += i & (-i)
        def pref(i):
            i += 1; r = 0
            while i > 0:
                r ^= bit[i]; i -= i & (-i)
            return r
        for u in range(n):
            d = 1 << (ord(s[u]) - 97)
            add(tin[u], d); add(tout[u] + 1, d)
        def lca(a, b):
            if dep[a] < dep[b]: a, b = b, a
            diff = dep[a] - dep[b]; k = 0
            while diff:
                if diff & 1: a = par[k][a]
                diff >>= 1; k += 1
            if a == b: return a
            for k in range(LOG - 1, -1, -1):
                if par[k][a] != par[k][b]:
                    a = par[k][a]; b = par[k][b]
            return par[0][a]
        cur = list(s); res = []
        for q in queries:
            t = q.split()
            if t[0] == 'update':
                u = int(t[1]); c = ord(t[2]) - 97
                d = (1 << (ord(cur[u]) - 97)) ^ (1 << c)
                add(tin[u], d); add(tout[u] + 1, d)
                cur[u] = t[2]
            else:
                u, v = int(t[1]), int(t[2])
                w = lca(u, v)
                mask = pref(tin[u]) ^ pref(tin[v]) ^ (1 << (ord(cur[w]) - 97))
                res.append(bin(mask).count('1') <= 1)
        return res

