class Solution {
public:
    vector<bool> palindromeQueries(int n, vector<vector<int>>& edges, string s, vector<string>& queries) {
        int LOG = 1; while ((1 << LOG) < n) LOG++;
        vector<vector<int>> adj(n);
        for (auto& e : edges) { adj[e[0]].push_back(e[1]); adj[e[1]].push_back(e[0]); }
        vector<int> dep(n), tin(n), tout(n);
        vector<vector<int>> par(LOG, vector<int>(n, 0));
        int timer = 0;
        vector<array<int,3>> stk{{0, -1, 0}};
        while (!stk.empty()) {
            auto [u, p, ph] = stk.back(); stk.pop_back();
            if (ph) { tout[u] = timer++; continue; }
            tin[u] = timer++;
            par[0][u] = p < 0 ? 0 : p;
            dep[u] = p < 0 ? 0 : dep[p] + 1;
            stk.push_back({u, p, 1});
            for (int w : adj[u]) if (w != p) stk.push_back({w, u, 0});
        }
        for (int k = 1; k < LOG; k++)
            for (int u = 0; u < n; u++) par[k][u] = par[k-1][par[k-1][u]];
        int sz = 2*n + 2;
        vector<int> fen(sz, 0);
        auto add = [&](int i, int d){ for (i++; i < sz; i += i & (-i)) fen[i] ^= d; };
        auto pref = [&](int i){ int r = 0; for (i++; i > 0; i -= i & (-i)) r ^= fen[i]; return r; };
        for (int u = 0; u < n; u++) { int d = 1 << (s[u]-'a'); add(tin[u], d); add(tout[u]+1, d); }
        auto lca = [&](int a, int b) {
            if (dep[a] < dep[b]) swap(a, b);
            int diff = dep[a] - dep[b];
            for (int k = 0; diff; k++, diff >>= 1) if (diff & 1) a = par[k][a];
            if (a == b) return a;
            for (int k = LOG-1; k >= 0; k--)
                if (par[k][a] != par[k][b]) { a = par[k][a]; b = par[k][b]; }
            return par[0][a];
        };
        string cur = s; vector<bool> res;
        for (auto& q : queries) {
            istringstream ss(q); string tp; ss >> tp;
            if (tp == "update") {
                int u; char c; ss >> u >> c;
                int d = (1 << (cur[u]-'a')) ^ (1 << (c-'a'));
                add(tin[u], d); add(tout[u]+1, d);
                cur[u] = c;
            } else {
                int u, v; ss >> u >> v;
                int w = lca(u, v);
                int mask = pref(tin[u]) ^ pref(tin[v]) ^ (1 << (cur[w]-'a'));
                res.push_back(__builtin_popcount(mask) <= 1);
            }
        }
        return res;
    }
};

