class Solution {
    public List<Boolean> palindromeQueries(int n, int[][] edges, String s, List<String> queries) {
        int LOG = 1; while ((1 << LOG) < n) LOG++;
        List<List<Integer>> adj = new ArrayList<>();
        for (int i = 0; i < n; i++) adj.add(new ArrayList<>());
        for (int[] e : edges) { adj.get(e[0]).add(e[1]); adj.get(e[1]).add(e[0]); }
        int[] dep = new int[n], tin = new int[n], tout = new int[n];
        int[][] par = new int[LOG][n];
        int timer = 0;
        Deque<int[]> stk = new ArrayDeque<>();
        stk.push(new int[]{0, -1, 0});
        while (!stk.isEmpty()) {
            int[] top = stk.pop();
            int u = top[0], p = top[1], ph = top[2];
            if (ph == 1) { tout[u] = timer++; continue; }
            tin[u] = timer++;
            par[0][u] = p < 0 ? 0 : p;
            dep[u] = p < 0 ? 0 : dep[p] + 1;
            stk.push(new int[]{u, p, 1});
            for (int w : adj.get(u)) if (w != p) stk.push(new int[]{w, u, 0});
        }
        for (int k = 1; k < LOG; k++)
            for (int u = 0; u < n; u++) par[k][u] = par[k-1][par[k-1][u]];
        int sz = 2*n + 2;
        int[] fen = new int[sz];
        java.util.function.BiConsumer<Integer,Integer> add = (i, d) -> {
            for (i++; i < sz; i += i & (-i)) fen[i] ^= d;
        };
        java.util.function.IntUnaryOperator pref = i -> {
            int r = 0; for (i++; i > 0; i -= i & (-i)) r ^= fen[i]; return r;
        };
        for (int u = 0; u < n; u++) {
            int d = 1 << (s.charAt(u) - 'a');
            add.accept(tin[u], d); add.accept(tout[u] + 1, d);
        }
        char[] cur = s.toCharArray();
        List<Boolean> res = new ArrayList<>();
        for (String q : queries) {
            String[] t = q.split(" ");
            if (t[0].equals("update")) {
                int u = Integer.parseInt(t[1]);
                int c = t[2].charAt(0) - 'a';
                int d = (1 << (cur[u] - 'a')) ^ (1 << c);
                add.accept(tin[u], d); add.accept(tout[u] + 1, d);
                cur[u] = t[2].charAt(0);
            } else {
                int u = Integer.parseInt(t[1]), v = Integer.parseInt(t[2]);
                int a = u, b = v;
                if (dep[a] < dep[b]) { int tmp = a; a = b; b = tmp; }
                int diff = dep[a] - dep[b];
                for (int k = 0; diff > 0; k++, diff >>= 1) if ((diff & 1) == 1) a = par[k][a];
                int w;
                if (a == b) w = a;
                else {
                    for (int k = LOG - 1; k >= 0; k--)
                        if (par[k][a] != par[k][b]) { a = par[k][a]; b = par[k][b]; }
                    w = par[0][a];
                }
                int mask = pref.applyAsInt(tin[u]) ^ pref.applyAsInt(tin[v]) ^ (1 << (cur[w] - 'a'));
                res.add(Integer.bitCount(mask) <= 1);
            }
        }
        return res;
    }
}

