var palindromeQueries = function(n, edges, s, queries) {
    const LOG = Math.max(1, Math.ceil(Math.log2(Math.max(2, n))));
    const adj = Array.from({length: n}, () => []);
    for (const [u, v] of edges) { adj[u].push(v); adj[v].push(u); }
    const dep = Array(n).fill(0), tin = Array(n).fill(0), tout = Array(n).fill(0);
    const par = Array.from({length: LOG}, () => Array(n).fill(0));
    let timer = 0;
    const stk = [[0, -1, 0]];
    while (stk.length) {
        const [u, p, ph] = stk.pop();
        if (ph) { tout[u] = timer++; continue; }
        tin[u] = timer++;
        par[0][u] = p < 0 ? 0 : p;
        dep[u] = p < 0 ? 0 : dep[p] + 1;
        stk.push([u, p, 1]);
        for (const w of adj[u]) if (w !== p) stk.push([w, u, 0]);
    }
    for (let k = 1; k < LOG; k++)
        for (let u = 0; u < n; u++) par[k][u] = par[k-1][par[k-1][u]];
    const sz = 2*n + 2, fen = Array(sz).fill(0);
    const add = (i, d) => { for (i++; i < sz; i += i & (-i)) fen[i] ^= d; };
    const pref = (i) => { let r = 0; for (i++; i > 0; i -= i & (-i)) r ^= fen[i]; return r; };
    for (let u = 0; u < n; u++) {
        const d = 1 << (s.charCodeAt(u) - 97);
        add(tin[u], d); add(tout[u] + 1, d);
    }
    const lca = (a, b) => {
        if (dep[a] < dep[b]) [a, b] = [b, a];
        let diff = dep[a] - dep[b], k = 0;
        while (diff) { if (diff & 1) a = par[k][a]; diff >>= 1; k++; }
        if (a === b) return a;
        for (let kk = LOG - 1; kk >= 0; kk--)
            if (par[kk][a] !== par[kk][b]) { a = par[kk][a]; b = par[kk][b]; }
        return par[0][a];
    };
    const cur = s.split('');
    const res = [];
    for (const q of queries) {
        const t = q.split(' ');
        if (t[0] === 'update') {
            const u = +t[1], c = t[2].charCodeAt(0) - 97;
            const d = (1 << (cur[u].charCodeAt(0) - 97)) ^ (1 << c);
            add(tin[u], d); add(tout[u] + 1, d);
            cur[u] = t[2];
        } else {
            const u = +t[1], v = +t[2], w = lca(u, v);
            const mask = pref(tin[u]) ^ pref(tin[v]) ^ (1 << (cur[w].charCodeAt(0) - 97));
            let pc = 0, m = mask;
            while (m) { pc += m & 1; m >>= 1; }
            res.push(pc <= 1);
        }
    }
    return res;
};
